import{d as g,C as e,o as h,c as d,a3 as t,E as i,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"正易心法·第一章","description":"《正易心法》第一章——「落处」为全书纲领：卦画本身即自然现象的直接写照，学《易》须知卦画实义，不作纸上功夫。","frontmatter":{"title":"正易心法·第一章","description":"《正易心法》第一章——「落处」为全书纲领：卦画本身即自然现象的直接写照，学《易》须知卦画实义，不作纸上功夫。","category":"guide","aliases":["正易心法第一章","落处","羲皇易道"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-01.md","filePath":"yijing/zheng-yi-xin-fa/chapter-01.md","lastUpdated":1790647676000}'),u={name:"yijing/zheng-yi-xin-fa/chapter-01.md"},x=g({...u,setup(c){const o=[{id:"z1-01",label:"一、须知落处",showLabel:!0,sentences:[[{text:"羲皇",glossary:"xiHuang"},{text:"《易》道",glossary:"yidao"},"，包括万象。须知",{text:"落处",glossary:"luochu"},"，方可实用。"]],note:["伏羲所画的《易》道，涵盖天地万象；但必须知道它的「落处」，才能真正实用。"]},{id:"z1-02",label:"二、落处谓何",showLabel:!0,sentences:[["落处，谓知",{text:"卦画",glossary:"guahua"},"实义所在，不",{text:"盲诵",glossary:"mangSong"},"古人语也。"]],note:["所谓「落处」，是指知道每一卦画的真实义理所在，而不是盲目背诵古人的文字解说。「落处」是本章的核心词：不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点——禅宗语录里问「这一句话落处在哪里」，问的就是这个。"]},{id:"z1-03",label:"三、震坎艮得乾爻",showLabel:!0,sentences:[["如震得乾初爻，故雷自天下而发；坎得中爻，故月自天之中而运；艮得上爻，故山自天上而坠也；巽、离、兑得坤三爻亦然。"]],note:["比如震（☳）得一阳在最下，所以雷从天的下方发出；坎（☵）得一阳在中间，所以月亮在天的中间运行；艮（☶）得一阳在最上，所以山从天上坠落而成；巽、离、兑得坤之三爻（阴爻居不同位），道理一样。这里的关键不是「雷为什么响」，而是「震这一画为什么长成这样」——卦画的结构本身就在描述自然现象。"]},{id:"z1-04",label:"四、六爻与月候",showLabel:!0,sentences:[["又六爻相应，如一阳生于子月，应在卯月；二阳丑，应在三月；三阳寅，应在四月是也。"]],note:["又如六爻与月候相应：一阳生于子月（冬至，十一月），应在卯月（二月）；二阳生于丑月（十二月），应在三月；三阳生于寅月（正月），应在四月。这是「消息」——阴消阳息、阴阳进退的具体节律。"]},{id:"z1-05",label:"五、人事亦然",showLabel:!0,sentences:[["人事亦然。《易》道见于天地万物",{text:"曰用",glossary:"riyong"},"之间，能以此",{text:"消息",glossary:"xiaoxi"},"，皆得实用，方知羲皇画卦，不作",{text:"纸上功夫",glossary:"zhishang"},"也。"]],note:["人事的道理也一样。《易》道体现在天地万物的日用之间，能用这种方式去体察阴阳消长，才有真正的实用——这样才明白伏羲画卦，不是做纸上功夫。"]}],r=[{id:"xiHuang",term:"羲皇",pinyin:"xī huáng",meaning:"伏羲氏，传说中画八卦的人。书中用它指《易》的原始作者，而非文王、孔子。"},{id:"yidao",term:"《易》道",pinyin:"yì dào",meaning:"《易》所承载的道理。麻衣的用法特指卦画所呈现的自然之理，而非文字训诂。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"本章核心词。不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点；宋人语录常用，如「这一句话落处在哪里」。"},{id:"guahua",term:"卦画",pinyin:"guà huà",meaning:"卦的图象本身（阴阳爻线的排列），与「卦辞」相对。麻衣认为卦画是本体，文字是后加的。"},{id:"mangSong",term:"盲诵",pinyin:"máng sòng",meaning:"盲目背诵。批评只记文字、不知卦象的学习方式。"},{id:"xiaoxi",term:"消息",pinyin:"xiāo xī",meaning:"消长、进退。古义为阴消阳息，指阴阳变化的规律，非现代的「消息／信息」。"},{id:"riyong",term:"曰用",pinyin:"yuē yòng",meaning:"「曰」通「日」，日用即每日生活。谓《易》道就体现在日常之间。"},{id:"zhishang",term:"纸上功夫",pinyin:"zhǐ shàng gōng fu",meaning:"只在文字上下功夫。批评脱离卦画的文字训诂一派。"}];return(m,a)=>{const l=e("DaoTextReading"),s=e("DaoKeywordCards");return h(),d("div",null,[a[0]||(a[0]=t(`<h1 id="正易心法·第一章" tabindex="-1">正易心法·第一章 <a class="header-anchor" href="#正易心法·第一章" aria-label="Permalink to &quot;正易心法·第一章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《正易心法》第一章，立全书第一个核心概念：<strong>落处</strong>。</p><p>麻衣的意思是：学《易》最大的病，是只读文字、背卦辞，却不知道卦画本身在说什么。<strong>「落处」就是卦画的实际对应</strong>——每一卦为什么长这个样子，它的形状本身就在描述自然现象。</p><p>举例的逻辑是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>震 ☳（一阳在下）→ 阳被压在阴下、奋发而出 → 这就是雷的样子</span></span>
<span class="line"><span>坎 ☵（一阳在中）→ 阳居中间而运行       → 这就是月的样子</span></span>
<span class="line"><span>艮 ☶（一阳在上）→ 阳在最上而坠落       → 这就是山的样子</span></span></code></pre></div><p><strong>不是因为「震为雷」这三个字，而是因为画象本身就是雷的样子。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>这里有一个隐含的批评对象：<strong>汉代以来的易学传统</strong>。汉儒治《易》重卦辞爻辞的文字训诂、纳甲飞伏的复杂规则、十翼的义理阐发——麻衣认为这些都是舍本逐末：<strong>文字是后加的，卦画才是本体。</strong></p><p>类比：就像学音乐，只背乐理术语，却不听声音本身。</p><p>而「消息」二字也值得深究：</p><ul><li><strong>消</strong> = 阴长阳消</li><li><strong>息</strong> = 阳长阴消</li><li>六爻与月份相应，正是消息规律的具体体现</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>抓住「落处」这个词——它是<strong>方法论</strong>，不是第一条易理；</li><li>把三男卦（震坎艮）的图自己画一遍，看「一阳在各爻位」如何对应雷、月、山；</li><li>读完之后回头问自己：我读《易》时，是在找落处，还是在盲诵？</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>落处</strong>：知卦画实义所在，不盲诵古人语。</li><li><strong>以象观物</strong>：卦画不是任意符号，而是自然现象的直接写照。</li><li><strong>三男卦的位序</strong>：一阳在初／中／上 → 雷自下发、月居中运、山自上坠。</li><li><strong>消息</strong>：六爻与月令相应，是阴阳进退的节律。</li><li><strong>日用</strong>：「曰」通「日」，易道见于日常，方得实用。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,17)),i(l,{colophon:"羲皇易道 · 须知落处 · 卦画实义 · 不作纸上功夫",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第一章原文",sections:o,glossary:r}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本（如「曰用」之「曰」、「一阳丑」等），不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(s,{items:[{term:"落处",pinyin:["luò","chù"],meaning:"本章核心词。不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点；宋人语录常用，如「这一句话落处在哪里」。"},{term:"卦画",pinyin:["guà","huà"],meaning:"卦的图象本身（阴阳爻线的排列），与「卦辞」相对。麻衣认为卦画是本体，文字是后加的。"},{term:"消息",pinyin:["xiāo","xī"],meaning:"消长、进退。古义为阴消阳息，指阴阳变化的规律，非现代的「消息／信息」。"},{term:"曰用",pinyin:["yuē","yòng"],meaning:"「曰」通「日」，日用即每日生活。谓《易》道就体现在日常之间。"},{term:"纸上功夫",pinyin:["zhǐ","shàng"],meaning:"只在文字上下功夫。批评脱离卦画的文字训诂一派。"}]}),a[3]||(a[3]=t('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章提出全书第一个核心概念：<strong>落处</strong>。</p><p>「落处」就是卦画的<strong>实际对应</strong>——每一卦为什么长这个样子，它的形状本身就在描述自然现象：</p><ul><li>震 ☳ = 两阴爻在上、一阳爻在下 → 阳气被压在阴下，奋发而出 → 这就是雷的物理形态；</li><li>不是因为有「震为雷」这三个字，而是因为<strong>画象本身就是雷的样子</strong>。</li></ul><p>这是一种<strong>以象观物</strong>的认识论，与现代的「符号任意性」完全相反——<strong>卦画不是任意符号，而是自然现象的直接写照。</strong></p><h3 id="理-为什么要这样说" tabindex="-1">理：为什么要这样说 <a class="header-anchor" href="#理-为什么要这样说" aria-label="Permalink to &quot;理：为什么要这样说&quot;">​</a></h3><p>隐含的批评对象是<strong>汉代以来的易学传统</strong>：文字训诂、纳甲飞伏、义理阐发。麻衣认为这些都是舍本逐末。而「消息」二字正是全书的一个关节：</p><table tabindex="0"><thead><tr><th>字</th><th>义</th></tr></thead><tbody><tr><td>消</td><td>阴长阳消</td></tr><tr><td>息</td><td>阳长阴消</td></tr></tbody></table><p>六爻与月份相应，正是消息规律的具体体现——<strong>这直接连通到后文的月令与数术体系。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把「落处」当<strong>方法论</strong>记住：读任何一句话，先问它的落处在哪；</li><li>自己动手画一遍三男卦，看「一阳在各爻位」如何对应雷、月、山；</li><li>带着一个疑问往下读：<strong>为什么麻衣反对「辞」？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>伏羲所画的《易》道，涵盖天地万象。但必须知道它的「落处」，才能真正实用。</p><p>所谓「落处」，是指知道每一卦画的真实义理所在，而不是盲目背诵古人的文字解说。</p><p>比如：震（☳）得一阳在最下，所以雷从天的下方发出；坎（☵）得一阳在中间，所以月亮在天的中间运行；艮（☶）得一阳在最上，所以山从天上坠落而成；巽、离、兑得坤之三爻，道理一样。</p><p>又如六爻与月候相应：一阳生于子月（冬至，十一月），应在卯月（二月）；二阳生于丑月（十二月），应在三月；三阳生于寅月（正月），应在四月。</p><p>人事的道理也一样。《易》道体现在天地万物的日用之间，能用这种方式去体察阴阳消长，才有真正的实用——这样才明白，伏羲画卦不是做纸上功夫。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第一章不讲一条易理，而是给了一把尺子——<strong>读任何一句《易》，先问它的「落处」在哪。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「落处」——我读《易》（或读任何古书）时，是在找落处，还是在背现成答案？</li><li>「不作纸上功夫」——我学的东西里，哪些只是纸上功夫？</li><li>三男卦的位序——自己画一遍，有没有看出「位置即意义」？</li><li>「人事亦然」——「消息」这两个字，能不能用在我眼下的事上？</li><li>「山自天上而坠」——这个说法先存疑，等第十四章（<strong>钩子已挂</strong>）。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/preface">前序·陈抟传记</a></li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「艮为山」是象例，本章讲的是象的生法</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia">系辞下传</a> — 「观象制器」与本章「卦画即象」相参</li></ul>',24))])}}});export{b as __pageData,x as default};
